import pyomo.environ as pyo
from pyomo.contrib.appsi.solvers.highs import Highs


def solve(params):
    periods = list(range(5))
    # Unit-commitment style formulation.
    # Decision variables per period t:
    #   n0[t] : number of Type 0 generators operational
    #   n1[t] : number of Type 1 generators operational
    #   p0[t] : total power generated by Type 0 generators (MW)
    #   p1[t] : total power generated by Type 1 generators (MW)
    #   s0[t] : number of Type 0 generators started
    #   s1[t] : number of Type 1 generators started

    fixed_cost_type0 = params["fixed_cost_type0"]
    fixed_cost_type1 = params["fixed_cost_type1"]
    variable_cost_type0 = params["variable_cost_type0"]
    variable_cost_type1 = params["variable_cost_type1"]
    start_cost_type0 = params["start_cost_type0"]
    start_cost_type1 = params["start_cost_type1"]
    demand = params["demand"]
    min_output_type0 = params["min_output_type0"]
    max_output_type0 = params["max_output_type0"]
    min_output_type1 = params["min_output_type1"]
    max_output_type1 = params["max_output_type1"]
    capacity_req = params["capacity_req"]
    max_operational_type0 = params["max_operational_type0"]
    max_operational_type1 = params["max_operational_type1"]
    max_start_period0_type0 = params["max_start_period0_type0"]
    max_start_period0_type1 = params["max_start_period0_type1"]

    model = pyo.ConcreteModel()
    model.T = pyo.Set(initialize=periods, ordered=True)

    model.n0 = pyo.Var(model.T, domain=pyo.NonNegativeIntegers, bounds=(0, max_operational_type0))
    model.n1 = pyo.Var(model.T, domain=pyo.NonNegativeIntegers, bounds=(0, max_operational_type1))
    model.p0 = pyo.Var(model.T, domain=pyo.NonNegativeReals)
    model.p1 = pyo.Var(model.T, domain=pyo.NonNegativeReals)
    model.s0 = pyo.Var(model.T, domain=pyo.NonNegativeIntegers)
    model.s1 = pyo.Var(model.T, domain=pyo.NonNegativeIntegers)

    def obj_rule(mdl):
        return (
            sum(fixed_cost_type0 * mdl.n0[t] + fixed_cost_type1 * mdl.n1[t] for t in mdl.T)
            + sum(variable_cost_type0 * mdl.p0[t] + variable_cost_type1 * mdl.p1[t] for t in mdl.T)
            + sum(start_cost_type0 * mdl.s0[t] + start_cost_type1 * mdl.s1[t] for t in mdl.T)
        )

    model.total_cost = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Demand satisfaction
    def demand_rule(mdl, t):
        return mdl.p0[t] + mdl.p1[t] >= demand[t]

    model.demand_con = pyo.Constraint(model.T, rule=demand_rule)

    # Output bounds per type given operational counts
    def p0_upper_rule(mdl, t):
        return mdl.p0[t] <= max_output_type0 * mdl.n0[t]

    def p0_lower_rule(mdl, t):
        return mdl.p0[t] >= min_output_type0 * mdl.n0[t]

    def p1_upper_rule(mdl, t):
        return mdl.p1[t] <= max_output_type1 * mdl.n1[t]

    def p1_lower_rule(mdl, t):
        return mdl.p1[t] >= min_output_type1 * mdl.n1[t]

    model.p0_upper_con = pyo.Constraint(model.T, rule=p0_upper_rule)
    model.p0_lower_con = pyo.Constraint(model.T, rule=p0_lower_rule)
    model.p1_upper_con = pyo.Constraint(model.T, rule=p1_upper_rule)
    model.p1_lower_con = pyo.Constraint(model.T, rule=p1_lower_rule)

    # Capacity requirement: total max output of operational generators
    def cap_req_rule(mdl, t):
        return max_output_type0 * mdl.n0[t] + max_output_type1 * mdl.n1[t] >= capacity_req[t]

    model.capacity_req_con = pyo.Constraint(model.T, rule=cap_req_rule)

    # Period 0 start limits
    model.start0_0_con = pyo.Constraint(expr=model.s0[0] <= max_start_period0_type0)
    model.start0_1_con = pyo.Constraint(expr=model.s1[0] <= max_start_period0_type1)

    # Subsequent period start limits: starts <= previous period operational count
    def start0_rule(mdl, t):
        if t == 0:
            return pyo.Constraint.Skip
        return mdl.s0[t] <= mdl.n0[t - 1]

    def start1_rule(mdl, t):
        if t == 0:
            return pyo.Constraint.Skip
        return mdl.s1[t] <= mdl.n1[t - 1]

    model.start0_con = pyo.Constraint(model.T, rule=start0_rule)
    model.start1_con = pyo.Constraint(model.T, rule=start1_rule)

    # Operational count <= previous operational count + current starts
    def op0_rule(mdl, t):
        if t == 0:
            return mdl.n0[t] <= mdl.s0[t]
        return mdl.n0[t] <= mdl.n0[t - 1] + mdl.s0[t]

    def op1_rule(mdl, t):
        if t == 0:
            return mdl.n1[t] <= mdl.s1[t]
        return mdl.n1[t] <= mdl.n1[t - 1] + mdl.s1[t]

    model.op0_con = pyo.Constraint(model.T, rule=op0_rule)
    model.op1_con = pyo.Constraint(model.T, rule=op1_rule)

    Highs().solve(model)

    obj_val = float(pyo.value(model.total_cost))
    return {"objective": obj_val, "status": "optimal"}